static uintptr_t Module(DWORD pid,const wchar_t* name){HANDLE snapshot=CreateToolhelp32Snapshot(TH32CS_SNAPMODULE|TH32CS_SNAPMODULE32,pid);if(snapshot==INVALID_HANDLE_VALUE)return 0;MODULEENTRY32W entry={sizeof(entry)};uintptr_t result=0;if(Module32FirstW(snapshot,&entry))do{if(!_wcsicmp(entry.szModule,name)){result=reinterpret_cast<uintptr_t>(entry.modBaseAddr);break;}}while(Module32NextW(snapshot,&entry));CloseHandle(snapshot);return result;}
