 wchar_t own[MAX_PATH]={};GetModuleFileNameW(nullptr,own,MAX_PATH);std::wstring dll(own);dll.resize(dll.find_last_of(L"\\/")+1);dll+=L"WolfFreecam.dll";if(GetFileAttributesW(dll.c_str())==INVALID_FILE_ATTRIBUTES){std::wcerr<<L"Missing "<<dll<<L"\n";return 3;}
 DWORD access=check?(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ):(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ|PROCESS_VM_WRITE|PROCESS_VM_OPERATION|PROCESS_CREATE_THREAD);HANDLE process=OpenProcess(access,FALSE,pid);if(!process){std::cerr<<"OpenProcess failed: "<<GetLastError()<<"\n";return 4;}
 auto exe=Module(pid,L"Wolf2.exe");IMAGE_DOS_HEADER dos={};IMAGE_NT_HEADERS32 nt={};SIZE_T read=0;bool supported=exe&&ReadProcessMemory(process,reinterpret_cast<void*>(exe),&dos,sizeof(dos),&read)&&dos.e_magic==IMAGE_DOS_SIGNATURE&&dos.e_lfanew>0&&dos.e_lfanew<0x100000&&ReadProcessMemory(process,reinterpret_cast<void*>(exe+dos.e_lfanew),&nt,sizeof(nt),&read)&&nt.Signature==IMAGE_NT_SIGNATURE&&nt.FileHeader.TimeDateStamp==0x562b029a&&nt.OptionalHeader.SizeOfImage==0x1a9a000;
